<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed} from 'vue'
import {Globe2,Activity,Wallet,Users,ShieldCheck,Server,Plus,Settings2,ArrowUpRight,ArrowRight,RefreshCw,Download,Check,Clock3,Search,AlertTriangle,Bell,Ticket,Package,Pencil,Trash2,FileText,Pause,Play,LockKeyhole} from 'lucide-vue-next'
import {api,action,cash,date,labels,orderLabel,orderTone,renewalAttention,notify,download,key,subscriptionRegions,regionLabel,type Row} from './lib'
import DataTable from './components/DataTable.vue'
import ProxyTable from './components/ProxyTable.vue'
import Modal from './components/Modal.vue'
import ConfigEditor from './components/ConfigEditor.vue'
import ProgressTrack from './components/ProgressTrack.vue'
import AdminMembership from './components/AdminMembership.vue'
import CheckoutResult from './components/CheckoutResult.vue'
import PaymentPanel from './components/PaymentPanel.vue'
import PaymentTrace from './components/PaymentTrace.vue'
import CheckoutLinks from './components/CheckoutLinks.vue'
import OrderBilling from './components/OrderBilling.vue'
const props=defineProps<{route:string;user:Row}>();const emit=defineEmits<{refresh:[];'public-refresh':[]}>()
const data=ref<Row>({}),rows=ref<Row[]>([]),settings=ref<Row>({}),error=ref(''),busy=ref(false),loading=ref(true),selected=ref<string[]>([]),modal=ref(''),form=ref<Row>({}),detail=ref<Row>({}),codes=ref<string[]>([]),configGroup=ref(''),configTab=ref('site'),status=ref('')
const period=ref('day'),start=ref(new Date(Date.now()-30*86400000).toLocaleDateString('en-CA')),end=ref(new Date().toLocaleDateString('en-CA')),includeAdmin=ref(false),mutationKey=ref(key())
const page=computed(()=>props.route.replace('/admin','').slice(1)||'overview')
const titles:Row={membership:'会员管理',overview:'运营概览',orders:'支付全监控',finance:'财务报表',users:'账户管理',topups:'充值审核',codes:'兑换码管理',products:'服务与定价',risk:'风控监控',resources:'代理管理',announcements:'公告中心',audit:'操作审计',settings:'站点设置'}
const subtitles:Row={membership:'管理消费等级、客户权益及指定等级，变更记录纳入操作审计。',overview:'从经营、资金到服务状态，聚焦真正需要关注的变化。',orders:'每笔订单有迹可循，详细阶段与处理记录尽在掌握。',finance:'按时间与账户核对入账、消费及余额，默认排除管理员。',users:'集中管理账户权限、服务单价和资金调整。',topups:'核实真实到账后再入账，每次审核都有记录。',codes:'按面值发行、批量管理，并导出一行一个的 TXT。',products:'配置服务展示与标准报价，历史订单保留当时价格。',risk:'定位异常请求和访问来源，在风险扩大前及时处理。',resources:'统一管理代理资源，配置排队、并发与安全重试策略。',announcements:'将重要消息送到登录页与客户工作台。',audit:'敏感操作可追溯，记录操作者、时间、来源和结果。',settings:'塑造你的品牌，管理服务约定与平台基础配置。'}
const filteredRows=computed(()=>status.value?rows.value.filter(x=>x.status===status.value):rows.value)
const topupPending=computed(()=>rows.value.filter(x=>x.status==='pending').length)
const chartMax=computed(()=>Math.max(1,...(data.value.trend||[]).map((x:Row)=>Math.max(Number(x.credited),Number(x.spent)))))
const orderCols=[{key:'order',label:'订单 / 订阅账号'},{key:'owner',label:'所属客户'},{key:'product_name',label:'套餐'},{key:'fee',label:'服务费报价'},{key:'status',label:'处理状态'},{key:'source',label:'来源'},{key:'created_at',label:'创建时间'},{key:'action',label:'操作'}]
const financeQuery=()=>`?period=${period.value}&start=${start.value}&end=${end.value}&include_admin=${includeAdmin.value}`
async function load(){error.value='';loading.value=true;try{selected.value=[];if(page.value==='membership'){}else if(page.value==='overview')data.value=await api('/admin/overview');else if(page.value==='finance')data.value=await api('/admin/finance'+financeQuery());else if(page.value==='risk')data.value=await api('/admin/risk');else if(page.value==='settings'){settings.value=await api('/admin/settings')}else{rows.value=(await api('/admin/'+page.value)).items;if(page.value==='resources')settings.value=await api('/admin/settings')}}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;await action(fn);busy.value=false}
async function config(group:string){await action(async()=>{settings.value=await api('/admin/settings');configGroup.value=group;modal.value='config'})}
function open(kind:string,row:Row={}){form.value=JSON.parse(JSON.stringify(row));mutationKey.value=key();if(kind==='user'){form.value={email:'',name:'',role:'member',status:'active',password:'',...form.value,fee_R:row.fee_override==null?'':Number(row.fee_override)/100}}if(kind==='balance')form.value={id:row.id,email:row.email,amount_R:0,reason:''};if(kind==='pricing')form.value={fee_R:''};if(kind==='codes')form.value={count:10,amount_R:100,days:365};if(kind==='product')form.value.fee_R=Number(row.fee)/100;if(kind==='announcement')form.value={title:'',body:'',tone:'info',published:false,login_visible:true,sort:0,starts_at:null,ends_at:null,...form.value};if(kind==='resource')form.value={name:'',endpoint:'',country:'PH',vendor:'other',ip_mode:'dynamic',enabled:true,weight:1,capacity:1,...form.value};if(kind==='block')form.value={ip:row.ip||'',minutes:60,reason:''};if(kind==='announcement'){for(const k of ['starts_at','ends_at'])if(form.value[k]){const d=new Date(form.value[k]);form.value[k]=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}}modal.value=kind}
async function order(row:Row){await action(async()=>{detail.value=await api('/admin/orders/'+row.id);form.value={note:detail.value.order.note};modal.value='order'})}
async function save(){await run(async()=>{const f=form.value;switch(modal.value){case 'user':if(f.id)await api('/admin/users/'+f.id,'PATCH',{email:f.email,name:f.name,role:f.role,status:f.status,fee_override:f.fee_R===''?null:Math.round(f.fee_R*100),password:f.password||''});else await api('/admin/users','POST',{email:f.email,name:f.name,role:f.role,password:f.password});break;case 'balance':await api('/admin/users/'+f.id+'/balance','POST',{amount:Math.round(f.amount_R*100),reason:f.reason},{'Idempotency-Key':mutationKey.value});emit('refresh');break;case 'pricing':await api('/admin/users/pricing','POST',{ids:selected.value,fee_override:f.fee_R===''?null:Math.round(f.fee_R*100)});break;case 'review':await api('/admin/topups/'+f.id+'/review','POST',{action:f.action,note:f.note});break;case 'codes':{const v=await api('/admin/codes','POST',{count:f.count,amount:Math.round(f.amount_R*100),days:f.days});codes.value=v.codes;download('xupay-'+v.batch+'.txt',v.codes.join('\r\n'));break}case 'product':await api('/admin/products/'+f.id,'PUT',{name:f.name,description:f.description,fee:Math.round(f.fee_R*100),enabled:f.enabled,sort:f.sort,tag:f.tag,features:f.features});emit('public-refresh');break;case 'announcement':await api('/admin/announcements'+(f.id?'/'+f.id:''),f.id?'PUT':'POST',{title:f.title,body:f.body,tone:f.tone,published:f.published,login_visible:f.login_visible,sort:f.sort,starts_at:f.starts_at?new Date(f.starts_at).toISOString():null,ends_at:f.ends_at?new Date(f.ends_at).toISOString():null});emit('public-refresh');break;case 'resource':await api('/admin/resources'+(f.id?'/'+f.id:''),f.id?'PUT':'POST',{name:f.name,endpoint:f.endpoint,country:f.country,vendor:f.vendor,ip_mode:f.ip_mode,enabled:f.enabled,weight:f.weight,capacity:f.capacity,is_global:!!f.is_global});break;case 'block':await api('/admin/blocks','POST',f);break;case 'order':await api('/admin/orders/'+detail.value.order.id,'PATCH',{note:f.note});break};notify('操作已完成');modal.value='';await load()})}
async function batchCodes(operation:string){if(!selected.value.length){notify('请先选择兑换码');return}if(operation!=='export'){form.value={operation,ids:[...selected.value]};modal.value='codeConfirm';return}await run(async()=>{const v=await api('/admin/codes/batch','POST',{ids:selected.value,action:'export'});download('xupay-codes.txt',v.codes.join('\r\n'));notify('已导出有效且未使用的兑换码')})}
const modalTitle=computed(()=>({user:form.value.id?'编辑账户':'创建账户',balance:'调整账户余额',pricing:'批量设置服务单价',review:'审核充值申请',codes:'发行兑换码',product:'编辑服务方案',announcement:form.value.id?'编辑公告':'发布新公告',resource:form.value.id?'编辑代理资源':'添加代理资源',block:'限制访问来源',order:'订单完整记录',config:'配置 · '+({risk:'风控规则',payment:'站内付款',scheduler:'队列调度',billing:'US 账单资料',proxy:'代理设置',tiers:'会员等级'} as Row)[configGroup.value],delete:'确认删除',codeConfirm:'批量管理兑换码'} as Row)[modal.value]||'详情')
let refreshTimer:ReturnType<typeof setInterval>;onMounted(()=>{load();refreshTimer=setInterval(()=>{if(modal.value==='order'&&!busy.value){api('/admin/orders/'+detail.value.order.id).then(v=>{if(modal.value==='order'&&v.order.id===detail.value.order.id)detail.value=v}).catch(()=>{})}if(!busy.value&&!modal.value&&!loading.value&&!selected.value.length&&document.visibilityState==='visible'&&['overview','orders','risk'].includes(page.value))load()},15000)});onUnmounted(()=>clearInterval(refreshTimer))
</script>
<template><div class="page-heading"><div><span class="eyebrow">OPERATIONS / {{page.toUpperCase()}}</span><h1>{{titles[page]}}</h1><p>{{subtitles[page]}}</p></div><div class="actions"><button class="icon-btn bordered" @click="load" :disabled="loading" aria-label="刷新数据"><RefreshCw :size="17" :class="{spinning:loading}"/></button><button v-if="page==='users'" class="btn primary" @click="open('user')"><Plus :size="17"/>创建账户</button><button v-if="page==='codes'" class="btn primary" @click="open('codes')"><Plus :size="17"/>发行兑换码</button><button v-if="page==='announcements'" class="btn primary" @click="open('announcement')"><Plus :size="17"/>新建公告</button><button v-if="page==='risk'" class="btn primary" @click="config('risk')"><Settings2 :size="17"/>风控配置</button><button v-if="page==='resources'" class="btn primary" @click="open('resource')"><Plus :size="17"/>添加资源</button><button v-if="page==='products'" class="btn secondary" @click="config('tiers')"><Settings2 :size="17"/>会员等级</button></div></div><div v-if="error" class="alert danger">{{error}}<button @click="load">重试</button></div>
<template v-if="page==='overview'"><div class="ops-banner"><div><span class="live-dot"/><b>平台运行正常</b><span>客户服务、账本与运营管理已就绪</span></div><span class="pill amber">结账准备已接通 · 付款待接入</span></div><div class="stats-grid four"><article class="stat" v-for="s in [{k:'customers',n:'客户账户',i:Users,u:'位'},{k:'balance',n:'客户可用余额',i:Wallet,u:'R',money:true},{k:'frozen',n:'客户冻结余额',i:LockKeyhole,u:'R',money:true},{k:'orders',n:'全部订单',i:Activity,u:'笔'}]" :key="s.k"><div class="stat-label">{{s.n}}<component :is="s.i" :size="18"/></div><strong>{{s.money?cash(data.stats?.[s.k]):data.stats?.[s.k]||0}}<small>{{s.u}}</small></strong><span class="muted">{{s.money?'默认排除管理员':'实时业务记录'}}</span></article></div><div class="ops-columns"><section class="panel focus-panel"><div class="panel-heading"><h2>现在需要关注</h2><span class="eyebrow">ACTION CENTER</span></div><a href="#/admin/topups" class="attention-row"><span class="icon-tile amber-tile"><Wallet :size="21"/></span><div><b>待审核充值</b><small>核实凭据后为客户入账</small></div><strong>{{data.stats?.pending_topups||0}}</strong><ArrowUpRight :size="18"/></a><a href="#/admin/risk" class="attention-row"><span class="icon-tile"><ShieldCheck :size="21"/></span><div><b>未核查风险事件</b><small>异常请求与权限拦截</small></div><strong>{{data.stats?.risks||0}}</strong><ArrowUpRight :size="18"/></a><a href="#/admin/resources" class="attention-row"><span class="icon-tile blue-tile"><Server :size="21"/></span><div><b>可用资源</b><small>已启用代理与调度策略</small></div><strong>{{data.stats?.resources||0}}</strong><ArrowUpRight :size="18"/></a></section><section class="panel queue-panel"><span class="eyebrow">QUEUE STATUS</span><h2>服务调度</h2><div class="queue-ring"><strong>{{data.stats?.active_orders||0}}</strong><span>执行中</span></div><div class="queue-details"><span>全局并发<b>{{data.scheduler?.max_parallel||2}}</b></span><span>每客户并发<b>{{data.scheduler?.per_user_parallel||1}}</b></span><span>队列状态<b>{{data.scheduler?.paused?'已暂停':'结账队列运行中'}}</b></span></div></section></div><div class="section-heading"><h2>最近订单</h2><a href="#/admin/orders">进入全监控<ArrowRight :size="16"/></a></div><div class="panel"><DataTable :rows="data.orders||[]" :columns="orderCols.filter(c=>!['fee','source'].includes(c.key))" :searchable="false"><template #order="{row}"><b>{{row.email}}</b><small class="mono">{{row.id.slice(0,12)}}</small></template><template #status="{row}"><span class="badge order-status" :class="orderTone(row)">{{orderLabel(row)}}</span></template><template #created_at="{row}">{{date(row.created_at)}}</template><template #action="{row}"><button class="text-btn" @click="order(row)">详情</button></template></DataTable></div></template>
<template v-else-if="page==='orders'"><div class="filter-strip"><button class="btn secondary" @click="config('payment')"><Settings2 :size="16"/>订阅流程配置</button><label>订单状态<select v-model="status"><option value="">全部状态</option><option v-for="s in ['draft','queued','processing','awaiting_payment','review','succeeded','failed','cancelled']" :key="s" :value="s">{{labels[s]}}</option></select></label><span class="callout-inline"><ShieldCheck :size="16"/>完整阶段记录由服务器投影，不返回上游原始请求。</span></div><div class="panel"><DataTable :rows="filteredRows" :columns="orderCols"><template #order="{row}"><b>{{row.email}}</b><small class="mono">{{row.id.slice(0,12)}}</small></template><template #fee="{row}">{{cash(row.fee)}} R</template><template #status="{row}"><span class="badge order-status" :class="orderTone(row)">{{orderLabel(row)}}</span></template><template #source="{row}">{{row.source==='api'?'API 接入':'客户页面'}}</template><template #created_at="{row}">{{date(row.created_at)}}</template><template #action="{row}"><button class="text-btn" @click="order(row)">完整流程</button></template></DataTable></div></template>
<AdminMembership v-else-if="page==='membership'" @changed="emit('refresh');emit('public-refresh')"/><template v-else-if="page==='finance'"><form class="filter-strip" @submit.prevent="load"><div class="tabs compact"><button type="button" v-for="(n,k) in {day:'每日',week:'每周',month:'每月',year:'每年'}" :key="k" :class="{active:period===k}" @click="period=k;load()">{{n}}</button></div><input type="date" v-model="start" required aria-label="开始日期"/><span>至</span><input type="date" v-model="end" required aria-label="结束日期"/><label class="checkbox-label"><input v-model="includeAdmin" type="checkbox" @change="load"/>包含管理员</label><button class="btn secondary">查询</button><a class="btn secondary" :href="'/api/admin/finance/export'+financeQuery()"><Download :size="16"/>导出</a></form><div class="stats-grid four"><article class="stat" v-for="s in [{n:'区间充值入账',v:data.totals?.credited},{n:'区间服务消费',v:data.totals?.spent},{n:'当前可用余额',v:data.current?.balance},{n:'当前冻结金额',v:data.current?.frozen}]" :key="s.n"><div class="stat-label">{{s.n}}</div><strong>{{cash(s.v)}}<small>R</small></strong></article></div><div class="panel chart-panel"><div class="panel-heading"><h2>资金变动趋势</h2><div class="chart-legend"><span><i></i>充值</span><span><i></i>消费</span></div></div><div v-if="data.trend?.length" class="bar-chart"><div v-for="t in data.trend" :key="t.period" class="bar-group" :title="`${t.period}：充值 ${cash(t.credited)} R，消费 ${cash(t.spent)} R`"><div class="bar-pair"><i :style="{height:Math.max(2,Number(t.credited)/chartMax*150)+'px'}"></i><i :style="{height:Math.max(2,Number(t.spent)/chartMax*150)+'px'}"></i></div><small>{{t.period.slice(5)}}</small></div></div><div v-else class="empty compact-empty"><Activity :size="30"/><p>所选期间暂无资金流水</p></div><p class="muted small">按北京时间统计。区间人工调整：{{cash(data.totals?.adjusted)}} R；当前余额为实时快照，不等同于区间利润。</p></div><div class="section-heading"><h2>每位客户的资金明细</h2><span class="muted small">100 分 = 1 R</span></div><div class="panel"><DataTable :rows="data.users||[]" :columns="[{key:'email',label:'账户'},{key:'name',label:'称呼'},{key:'credited',label:'区间充值'},{key:'spent',label:'区间使用'},{key:'adjusted',label:'人工调整'},{key:'balance',label:'当前可用'},{key:'frozen',label:'当前冻结'},{key:'fee_override',label:'专属单价'},{key:'orders',label:'区间订单'}]"><template v-for="k in ['credited','spent','adjusted','balance','frozen']" #[k]="{row}">{{cash(row[k])}}</template><template #fee_override="{row}">{{row.fee_override==null?'按等级':cash(row.fee_override)+' R'}}</template></DataTable></div></template>
<template v-else-if="page==='users'"><div class="filter-strip"><span class="muted">已选 {{selected.length}} 个账号</span><button class="btn secondary" :disabled="!selected.length" @click="open('pricing')"><Settings2 :size="16"/>批量调整服务单价</button></div><div class="panel"><DataTable :rows="rows" selectable @selection="selected=$event" :columns="[{key:'account',label:'账户'},{key:'role',label:'权限 / 状态'},{key:'balance',label:'可用余额'},{key:'frozen',label:'冻结余额'},{key:'fee_override',label:'专属单价'},{key:'orders',label:'订单'},{key:'action',label:'操作'}]"><template #account="{row}"><b>{{row.name}}</b><small>{{row.email}}</small></template><template #role="{row}"><span class="badge" :class="row.status">{{labels[row.role]}} · {{labels[row.status]}}</span></template><template #balance="{row}">{{cash(row.balance)}} R</template><template #frozen="{row}">{{cash(row.frozen)}} R</template><template #fee_override="{row}">{{row.fee_override==null?'按等级':cash(row.fee_override)+' R'}}</template><template #action="{row}"><div class="actions"><button class="text-btn" @click="open('user',row)">编辑</button><button class="text-btn" @click="open('balance',row)">调账</button></div></template></DataTable></div></template>
<template v-else-if="page==='topups'"><div class="callout"><Wallet :size="18"/>待审核 {{topupPending}} 笔。只有核实真实到账后才确认入账，同一申请不会重复加款。</div><div class="panel"><DataTable :rows="rows" :columns="[{key:'email',label:'客户'},{key:'amount',label:'申请金额'},{key:'proof',label:'客户提供的核对信息'},{key:'status',label:'审核状态'},{key:'created_at',label:'申请时间'},{key:'action',label:'操作'}]"><template #amount="{row}"><b>{{cash(row.amount)}} R</b></template><template #status="{row}"><span class="badge order-status" :class="orderTone(row)">{{orderLabel(row)}}</span></template><template #created_at="{row}">{{date(row.created_at)}}</template><template #action="{row}"><button v-if="row.status==='pending'" class="text-btn" @click="open('review',{...row,action:'approve',note:''})">审核</button><span v-else class="muted">{{row.note||'—'}}</span></template></DataTable></div></template>
<template v-else-if="page==='codes'"><div class="filter-strip"><span class="muted">已选 {{selected.length}} 条</span><button class="btn secondary" :disabled="!selected.length||busy" @click="batchCodes('export')"><Download :size="16"/>导出 TXT</button><button class="btn secondary" :disabled="!selected.length||busy" @click="batchCodes('disable')">批量停用</button><button class="btn secondary danger-text" :disabled="!selected.length||busy" @click="batchCodes('delete')">批量删除</button></div><div class="panel"><DataTable :rows="rows" selectable @selection="selected=$event" :columns="[{key:'prefix',label:'兑换码标识'},{key:'amount',label:'面值'},{key:'batch',label:'发行批次'},{key:'status',label:'状态'},{key:'used_by',label:'兑换账户'},{key:'expires_at',label:'到期时间'}]"><template #prefix="{row}"><code>{{row.prefix}}</code></template><template #amount="{row}">{{cash(row.amount)}} R</template><template #status="{row}"><span class="badge order-status" :class="orderTone(row)">{{orderLabel(row)}}</span></template><template #expires_at="{row}">{{date(row.expires_at)}}</template></DataTable></div></template>
<template v-else-if="page==='products'"><div class="service-grid admin-products"><article class="service-card" v-for="p in rows" :key="p.id"><div class="actions"><span class="pill">{{p.tag}}</span><span class="badge" :class="p.enabled?'active':'disabled'">{{p.enabled?'展示中':'已隐藏'}}</span></div><h3>{{p.name}}</h3><p>{{p.description}}</p><div><b>{{cash(p.fee)}} R <small>/ 次服务</small></b><button class="icon-btn bordered" @click="open('product',p)" :aria-label="'编辑 '+p.name"><Pencil :size="17"/></button></div></article></div><div class="callout">上游订阅费用与平台服务费分开。当前套餐来自现有提链脚本支持范围，实际支付稍后接入。</div></template>
<template v-else-if="page==='risk'"><div class="stats-grid three"><article class="stat"><div class="stat-label">待核查事件<ShieldCheck :size="18"/></div><strong>{{data.items?.filter((r:Row)=>!r.resolved).length||0}}</strong><span class="muted">本次加载的最近 300 条内</span></article><article class="stat"><div class="stat-label">高风险事件<AlertTriangle :size="18"/></div><strong>{{data.items?.filter((r:Row)=>r.severity==='high').length||0}}</strong><span class="muted">登录异常、敏感接口越权</span></article><article class="stat"><div class="stat-label">生效中的来源限制<LockKeyhole :size="18"/></div><strong>{{data.blocks?.length||0}}</strong><span class="muted">到期后自动失效</span></article></div><div class="panel"><DataTable :rows="data.items||[]" :columns="[{key:'severity',label:'级别'},{key:'category',label:'事件'},{key:'email',label:'账户'},{key:'ip',label:'来源 IP'},{key:'detail',label:'说明'},{key:'created_at',label:'时间'},{key:'action',label:'处理'}]"><template #severity="{row}"><span class="badge" :class="row.severity">{{labels[row.severity]}}</span></template><template #category="{row}">{{({login_failed:'登录校验失败',login_rate:'登录限流',permission_denied:'权限拦截',rate_limit:'接口限流',order_rate:'订单限流',redeem_rate:'兑换限流'} as Row)[row.category]||row.category}}</template><template #created_at="{row}">{{date(row.created_at)}}</template><template #action="{row}"><div class="actions"><button v-if="!row.resolved" class="text-btn" :disabled="busy" @click="run(async()=>{await api('/admin/risk/'+row.id+'/resolve','POST',{});await load()})">已核查</button><span v-else class="muted">已处理</span><button class="text-btn danger-text" @click="open('block',row)">限制 IP</button></div></template></DataTable></div><div class="section-heading"><h2>访问来源限制</h2><button class="btn secondary" @click="open('block')"><Plus :size="16"/>新增限制</button></div><div class="panel"><DataTable :rows="data.blocks||[]" :columns="[{key:'ip',label:'IP'},{key:'reason',label:'原因'},{key:'expires_at',label:'解除时间'},{key:'action',label:'操作'}]"><template #expires_at="{row}">{{date(row.expires_at)}}</template><template #action="{row}"><button class="text-btn" @click="run(async()=>{await api('/admin/blocks/'+encodeURIComponent(row.ip),'DELETE');await load()})">立即解除</button></template></DataTable></div><p class="muted small">默认仅使用 TCP 连接来源，不信任客户端自行传入的转发头。部署反向代理时需明确配置可信代理。</p></template>
<template v-else-if="page==='resources'"><div class="ops-banner proxy-controls"><div><Server :size="20"/><b>代理与办理调度</b></div><div class="actions"><button class="btn secondary" @click="config('proxy')"><Settings2 :size="16"/>代理配置</button><button class="btn secondary" @click="config('payment')"><Settings2 :size="16"/>付款配置</button><button class="btn secondary" @click="config('scheduler')"><Settings2 :size="16"/>队列配置</button></div></div><div class="stats-grid four"><article class="stat" v-for="s in [{n:'全局并发上限',v:settings.scheduler?.max_parallel},{n:'单客户并发',v:settings.scheduler?.per_user_parallel},{n:'重试间隔',v:settings.scheduler?.retry_delay_seconds,u:'s'},{n:'单任务超时',v:settings.scheduler?.task_timeout_seconds,u:'s'}]" :key="s.n"><div class="stat-label">{{s.n}}</div><strong>{{s.v||0}}<small>{{s.u}}</small></strong></article></div><div class="global-proxy-banner"><Globe2 :size="20"/><div><b>续费全局代理：{{rows.find(r=>r.is_global)?.name||'尚未设置'}}</b><p>{{rows.find(r=>r.is_global)?.enabled?'续费管理菜单的独立取消与核实使用此代理；订阅办理全程沿用原订单代理。':'用于续费管理菜单。未配置、停用或占满时独立任务等待；订阅办理继续使用原订单代理。'}}</p></div></div><ProxyTable :rows="rows" :busy="busy" @refresh="load" @edit="open('resource',$event)" @remove="form={id:$event.id,path:'resources',name:$event.name};modal='delete'"/><div class="callout"><LockKeyhole :size="18"/>订阅办理按地区选择代理，整单沿用同一个端点。动态 IPRoyal 按原规则添加 session，动态 Cliproxy 每单生成独立 sid、有效 15 分钟；静态和其他厂商原样使用后台凭据。付款前检查出口 IP，漂移或检查失败即停止；粘性会话不能保证供应商绝不换 IP。独立续费管理使用全局代理。评分只代表连接质量，不代表 IP 风险分。</div></template>
<template v-else-if="page==='announcements'"><div class="announcement-cards"><article class="panel announcement-admin" v-for="a in rows" :key="a.id"><div class="actions"><span class="badge" :class="a.published?'active':'draft'">{{a.published?'已发布':'草稿'}}</span><span class="pill" v-if="a.login_visible">登录页展示</span><span class="muted small">排序 {{a.sort}}</span></div><h2>{{a.title}}</h2><p class="pre-wrap">{{a.body}}</p><footer><span>{{a.starts_at?date(a.starts_at):'立即生效'}} / {{a.ends_at?date(a.ends_at):'长期有效'}}</span><div class="actions"><button class="text-btn" @click="open('announcement',a)">编辑</button><button class="text-btn danger-text" @click="form={id:a.id,path:'announcements',name:a.title};modal='delete'">删除</button></div></footer></article><div v-if="!rows.length" class="panel empty"><Bell :size="32"/><h3>把重要消息告诉客户</h3><p>支持多条公告、展示排序与定时上下线。</p><button class="btn primary" @click="open('announcement')">新建第一条公告</button></div></div></template>
<template v-else-if="page==='audit'"><div class="panel"><DataTable :rows="rows" :columns="[{key:'created_at',label:'时间'},{key:'actor',label:'操作者'},{key:'action',label:'操作'},{key:'target',label:'目标'},{key:'detail',label:'说明'},{key:'ip',label:'来源 IP'}]"><template #created_at="{row}">{{date(row.created_at)}}</template><template #target="{row}"><span class="mono">{{row.target?.length>20?row.target.slice(0,12)+'…':row.target}}</span></template></DataTable></div></template>
<template v-else-if="page==='settings'"><div class="tabs settings-tabs"><button :class="{active:configTab==='site'}" @click="configTab='site'">品牌与服务</button><button :class="{active:configTab==='billing'}" @click="configTab='billing'">US 账单资料</button><button :class="{active:configTab==='tiers'}" @click="configTab='tiers'">会员等级</button></div><div class="panel form-panel" :style="configTab==='billing'?{maxWidth:'none'}:{}" v-if="settings[configTab]"><ConfigEditor :key="configTab" :group="configTab" :value="settings[configTab]" @saved="load();emit('public-refresh')"/></div></template>
<Modal v-if="modal" :title="modalTitle" :wide="['order','config'].includes(modal)" @close="modal=''">
<ConfigEditor v-if="modal==='config'" :group="configGroup" :value="settings[configGroup]" @saved="modal='';load();emit('public-refresh')"/>
<template v-else-if="modal==='delete'"><p>确认删除「{{form.name}}」？此操作会立即生效。</p><button class="btn danger" :disabled="busy" @click="run(async()=>{await api('/admin/'+form.path+'/'+form.id,'DELETE');modal='';await load();emit('public-refresh');notify('已删除')})">确认删除</button></template>
<template v-else-if="modal==='codeConfirm'"><p>对 {{form.ids.length}} 条记录执行{{form.operation==='delete'?'删除':'停用'}}。已兑换记录会保留，以便核对账本。</p><button class="btn danger" :disabled="busy" @click="run(async()=>{await api('/admin/codes/batch','POST',{ids:form.ids,action:form.operation});modal='';await load();notify('批量操作完成')})">确认操作</button></template>
<form v-else @submit.prevent="save">
<template v-if="modal==='user'"><div class="form-grid"><label>邮箱<input type="email" v-model="form.email" required/></label><label>称呼<input v-model="form.name" required maxlength="80"/></label><label>角色<select v-model="form.role"><option value="member">客户</option><option value="admin">管理员</option></select></label><label v-if="form.id">状态<select v-model="form.status"><option value="active">可用</option><option value="disabled">停用</option></select></label><label class="span2">{{form.id?'重设密码（不修改留空）':'初始密码'}}<input type="password" v-model="form.password" :required="!form.id" minlength="10" maxlength="72" autocomplete="new-password"/></label><label v-if="form.id">专属服务单价（R）<input v-model="form.fee_R" type="number" min="0" step="0.01" placeholder="留空：按套餐与等级"/></label></div></template>
<template v-else-if="modal==='balance'"><p>{{form.email}}</p><div class="callout">正数增加余额，负数扣减余额；不会改变冻结金额，所有调整保留账本记录。</div><label>调整金额（R）<div class="amount-control"><button type="button" @click="form.amount_R=Number(form.amount_R)-10">−</button><input v-model.number="form.amount_R" type="number" step="0.01" required/><button type="button" @click="form.amount_R=Number(form.amount_R)+10">+</button></div></label><label>调整原因<textarea v-model="form.reason" required minlength="2" maxlength="300" placeholder="请填写本次调整的业务依据"></textarea></label></template>
<template v-else-if="modal==='pricing'"><p>将调整选中的 {{selected.length}} 个账户，仅影响之后创建的订单。</p><label>专属服务单价（R）<input v-model="form.fee_R" type="number" min="0" step="0.01" placeholder="留空恢复套餐与等级定价"/></label></template>
<template v-else-if="modal==='review'"><div class="review-amount"><span>{{form.email}}</span><strong>{{cash(form.amount)}} R</strong></div><div class="callout pre-wrap">客户备注：{{form.proof||'未填写'}}</div><label>审核结果<select v-model="form.action"><option value="approve">已核实真实到账，同意入账</option><option value="reject">未核实到账，拒绝申请</option></select></label><label>审核说明<textarea required minlength="2" maxlength="300" v-model="form.note" placeholder="到账渠道、时间、核对结果"></textarea></label></template>
<template v-else-if="modal==='codes'"><div class="form-grid"><label>生成数量<input v-model.number="form.count" type="number" min="1" max="200" required/></label><label>每个面值（R）<input v-model.number="form.amount_R" type="number" min="1" max="100000" step="0.01" required/></label><label>有效天数<input v-model.number="form.days" type="number" min="1" max="3660" required/></label></div><div class="callout">生成后自动下载 TXT，每行一个兑换码。已发行不代表已入账，兑换成功后才进入账本。</div></template>
<template v-else-if="modal==='product'"><label>展示名称<input v-model="form.name" required maxlength="80"/></label><label>介绍<input v-model="form.description" maxlength="300"/></label><div class="form-grid"><label>服务费（R）<input v-model.number="form.fee_R" required type="number" min="0" step="0.01"/></label><label>标签<input v-model="form.tag" maxlength="40"/></label><label>排序<input v-model.number="form.sort" type="number"/></label><label class="switch-label"><input type="checkbox" v-model="form.enabled"/>展示此服务</label></div></template>
<template v-else-if="modal==='announcement'"><label>标题<input v-model="form.title" maxlength="150" required/></label><label>公告正文<textarea v-model="form.body" rows="6" maxlength="5000" required></textarea></label><div class="form-grid"><label>提醒类型<select v-model="form.tone"><option value="info">普通通知</option><option value="warning">重要提醒</option><option value="success">服务动态</option></select></label><label>排序<input v-model.number="form.sort" type="number"/></label><label>开始时间（选填）<input v-model="form.starts_at" type="datetime-local"/></label><label>结束时间（选填）<input v-model="form.ends_at" type="datetime-local"/></label><label class="checkbox-label"><input v-model="form.published" type="checkbox"/>立即发布 / 按时生效</label><label class="checkbox-label"><input v-model="form.login_visible" type="checkbox"/>同时展示在登录页</label></div></template>
<template v-else-if="modal==='resource'"><label>资源名称<input v-model="form.name" maxlength="80" required/></label><div class="form-grid"><label>代理厂商<select v-model="form.vendor" required><option value="iproyal">IPRoyal</option><option value="cliproxy">Cliproxy</option><option value="other">其他</option></select></label><label>代理类型<select v-model="form.ip_mode" required><option value="dynamic">动态</option><option value="static">静态</option></select></label></div><p class="muted small">{{form.ip_mode==='dynamic'&&form.vendor==='iproyal'?'每笔订阅生成独立 session，整单复用同一会话。':form.ip_mode==='dynamic'&&form.vendor==='cliproxy'?'每笔订阅生成独立 sid，固定 15 分钟，整单复用同一会话。':'直接使用填写的代理凭据，不自动添加或改写 session。'}}厂商和类型修改对新订单生效，已有订单沿用原代理会话。</p><label>代理地址<input v-model="form.endpoint" :required="!form.id" :placeholder="form.id?'留空保留原凭据':'host:port:user:password 或 socks5://user:pass@host:port'" autocomplete="off"/><small>默认 HTTP，也支持 HTTPS、SOCKS5、SOCKS5H。保存后不回显；编辑时留空保留原凭据。</small></label><div class="form-grid"><label>订阅地区<select v-model="form.country" required><option v-if="form.country&&!subscriptionRegions.some(r=>r.code===form.country)" :value="form.country" disabled>{{form.country}}（请重新选择）</option><option v-for="r in subscriptionRegions" :key="r.code" :value="r.code">{{r.name}} · {{r.code}} / {{r.currency}}</option></select><small>订单选择此地区时自动匹配本代理，实际出口须与所选地区一致。</small></label><label>单资源并发<input v-model.number="form.capacity" type="number" min="1" max="100" required/></label><label>权重<input v-model.number="form.weight" type="number" min="1" max="100" required/></label><label class="checkbox-label"><input v-model="form.enabled" type="checkbox"/>启用资源</label></div><label class="checkbox-label"><input v-model="form.is_global" type="checkbox"/>设为全局代理（独立续费管理）</label><p class="muted small">全局只能选一条；设置后替换原全局代理，不影响提链按地区匹配。</p></template>
<template v-else-if="modal==='block'"><label>来源 IP<input v-model="form.ip" required placeholder="公网 IPv4 或 IPv6"/></label><label>限制时长（分钟）<input v-model.number="form.minutes" type="number" min="1" max="10080" required/></label><label>原因<textarea v-model="form.reason" minlength="2" maxlength="300" required></textarea></label></template>
<template v-else-if="modal==='order'"><div class="detail-title"><div><h3>{{detail.order?.email}}</h3><p>{{detail.order?.owner}} / {{detail.order?.product_name}}</p><small class="mono">{{detail.order?.id}}</small><p v-if="detail.order?.checkout_flow">提链流程：<b>{{detail.order.checkout_flow==='legacy'?'旧提链':'新提链'}}</b><template v-if="detail.order.workflow==='subscription'"> → 付款及后续：<b>{{['legacy','cslive_browser'].includes(detail.order.subscription_flow)?'旧浏览器':detail.order.subscription_flow==='legacy_protocol'?'旧协议':'新流程'}}</b></template><template v-else> · 仅生成结账链接</template></p></div><span class="badge order-status" :class="orderTone(detail.order)">{{orderLabel(detail.order)}}</span></div><ProgressTrack :status="detail.order?.status" :payment-state="detail.payment?.state" :workflow="detail.order?.workflow" :renewal="detail.order?.renewal" :activation="detail.order?.activation"/><PaymentTrace :key="detail.order?.id" :order="detail.order" :payment="detail.payment" :billing="detail.billing" :checkout="detail.checkout" :links="detail.checkout_links||[]" :events="detail.trace||[]"/><CheckoutResult v-if="detail.order?.workflow!=='subscription'" :checkout="detail.checkout" :payment-state="detail.payment?.state"/><details class="business-records"><summary>结账链接历史 · {{(detail.checkout_links||[]).length}} 轮</summary><CheckoutLinks :links="detail.checkout_links||[]"/></details><details class="business-records" :open="detail.payment?.can_check||['review','action_required','preparing','quoted','submitting','checking'].includes(detail.payment?.state)"><summary>付款操作与详细状态</summary><PaymentPanel :order="detail.order" :payment="detail.payment" :admin="true" @refresh="order(detail.order)"/></details><div v-for="entry in detail.closures||[]" :key="entry.created_at" class="callout"><b>人工关闭记录</b><p>{{entry.actor}} · {{date(entry.created_at)}}</p><p>原因：{{entry.reason}}</p><p>关闭前付款状态：{{entry.prior_payment_state}}；{{entry.payment_submitted?'已提交过付款，需另行核实银行卡结果':'尚未提交付款'}}。冻结服务费已释放。</p></div><details class="business-records" v-if="detail.order?.workflow==='subscription'||detail.billing?.state!=='not_selected'"><summary>本单账单资料</summary><OrderBilling :billing="detail.billing"/></details><details class="business-records"><summary>业务记录与处理说明</summary><div class="timeline"><div v-for="(e,i) in detail.events" :key="i"><span class="timeline-dot"></span><small>{{date(e.created_at)}}</small><p>{{e.message}}</p></div></div></details><label>运营备注<textarea v-model="form.note" maxlength="1000" placeholder="仅记录业务处理依据，不要填写密钥或卡片信息"></textarea></label></template>
<div class="form-footer"><button type="button" class="btn secondary" @click="modal=''">取消</button><button class="btn primary" :disabled="busy"><Check :size="16"/>{{busy?'处理中…':modal==='codes'?'生成并导出 TXT':'确认保存'}}</button></div></form></Modal></template>

<style scoped>
.global-proxy-banner{display:flex;align-items:center;gap:14px;background:#edf7f2;border:1px solid #d8eae1;padding:18px 22px;border-radius:12px;margin-bottom:20px;color:#237459}.global-proxy-banner p{font-size:12px;margin:6px 0 0;color:#55756a}
@media(max-width:700px){.proxy-controls{align-items:flex-start;flex-direction:column;gap:14px}.proxy-controls>.actions{flex-wrap:wrap}.proxy-controls>.actions>.btn{padding:10px 12px}.global-proxy-banner{padding:16px;align-items:flex-start}.global-proxy-banner>svg{flex-shrink:0}}
</style>
